pub(super) async fn compatibility_attachment_rows(root:&std::path::Path,pool:&sqlx::AnyPool)->Value {
 use sqlx::Row;let pg=root.join(".pg-restoration-custody").exists();let mut result=serde_json::Map::new();
 for table in ["attachments","attachment_upload_receipts","attachment_families","attachment_version_records","attachment_version_changes","attachment_retirements","attachment_retained_byte_ledger"] {
  let columns:Vec<String>=if pg{sqlx::query_scalar("SELECT CAST(column_name AS TEXT) FROM information_schema.columns WHERE table_schema=current_schema() AND table_name=$1 ORDER BY ordinal_position").bind(table).fetch_all(pool).await.unwrap()}else{sqlx::query_scalar("SELECT name FROM pragma_table_info($1) ORDER BY cid").bind(table).fetch_all(pool).await.unwrap()};assert!(!columns.is_empty());
  let query=format!("SELECT {} FROM {table}",columns.iter().map(|name|format!("CAST(\"{name}\" AS TEXT)")).collect::<Vec<_>>().join(","));let rows=sqlx::query(&query).fetch_all(pool).await.unwrap();let mut values:Vec<Vec<Option<String>>>=rows.iter().map(|row|(0..columns.len()).map(|i|row.try_get::<Option<String>,_>(i).unwrap()).collect()).collect();values.sort();result.insert(table.into(),json!({"columns":columns,"rows":values}));
 }Value::Object(result)
}

