 let state=AppState{db:pool.clone(),jwt_secret:"owned-erasure-fixture".into(),base_url:"http://localhost".into(),search_index:crate::search::SearchIndex::new(std::path::PathBuf::from(format!("/tmp/mixed-fresh-read-index-{}",uuid::Uuid::new_v4().simple()))).unwrap(),oauth_cache:crate::auth::routes::OAuthStateCache::new(),ws_rooms:crate::sync::WsRooms::default()};
 let token=crate::auth::jwt::create_token_pair_for_session("owner","owner@test.invalid","member",&state.jwt_secret,Some("owner-session"),30).unwrap().access_token;let app=crate::spaces::attachments::router().merge(storage::attachment_versions::router()).with_state(state);let listener=tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();let base=format!("http://{}",listener.local_addr().unwrap());let server=tokio::spawn(async move{axum::serve(listener,app).await.unwrap()});let client=reqwest::Client::new();
